enum Status { ACTIVE, COMPLETED, CANCELLED }
record EnrollmentCompleted(UUID enrollmentId, UUID learnerId) {}

class Enrollment { // racine d'agregat
    private final UUID id;
    private final UUID learnerId;   // reference PAR IDENTITE (pas un objet Learner)
    private Status status = Status.ACTIVE;
    private final List<Object> events = new ArrayList<>();

    Enrollment(UUID id, UUID learnerId) {
        this.id = id;
        this.learnerId = learnerId;
    }

    void complete() {
        if (status != Status.ACTIVE)
            throw new IllegalStateException("seule une inscription active peut etre terminee");
        this.status = Status.COMPLETED;                     // invariant protege par la racine
        events.add(new EnrollmentCompleted(id, learnerId)); // fait metier enregistre
    }

    List<Object> pullEvents() {
        var e = List.copyOf(events);
        events.clear();
        return e;
    }
}
